-- Pi session files are stored relative to the data directory (`bots/<botId>/sessions/<file>`)
-- so a moved, restored or symlinked data directory keeps its sessions. Session files always live in
-- the fixed `<dataDir>/bots/<botId>/sessions/` folder, so any old absolute path is recognised by
-- that suffix (with the row's own Bot id), whatever data directory it was written under; `\`
-- separators from Windows are normalised first. Rows that do not end in exactly that structure keep
-- their value; the agent then refuses them with the recoverable `session_unavailable` error.
-- Idempotent: converted values no longer start with a separator or drive and are skipped.

UPDATE conversations SET pi_session_file='bots/'||bot_id||'/sessions/'||substr(replace(pi_session_file,'\','/'),instr(replace(pi_session_file,'\','/'),'/bots/'||bot_id||'/sessions/')+length('/bots/'||bot_id||'/sessions/'))
WHERE pi_session_file IS NOT NULL AND (substr(pi_session_file,1,1) IN ('/','\') OR substr(pi_session_file,2,1)=':') AND bot_id IS NOT NULL AND instr(replace(pi_session_file,'\','/'),'/bots/'||bot_id||'/sessions/')>0
  AND substr(replace(pi_session_file,'\','/'),instr(replace(pi_session_file,'\','/'),'/bots/'||bot_id||'/sessions/')+length('/bots/'||bot_id||'/sessions/'))<>'' AND substr(replace(pi_session_file,'\','/'),instr(replace(pi_session_file,'\','/'),'/bots/'||bot_id||'/sessions/')+length('/bots/'||bot_id||'/sessions/')) NOT IN ('.','..') AND instr(substr(replace(pi_session_file,'\','/'),instr(replace(pi_session_file,'\','/'),'/bots/'||bot_id||'/sessions/')+length('/bots/'||bot_id||'/sessions/')),'/')=0;

UPDATE bot_sessions SET pi_session_file='bots/'||bot_id||'/sessions/'||substr(replace(pi_session_file,'\','/'),instr(replace(pi_session_file,'\','/'),'/bots/'||bot_id||'/sessions/')+length('/bots/'||bot_id||'/sessions/'))
WHERE pi_session_file IS NOT NULL AND (substr(pi_session_file,1,1) IN ('/','\') OR substr(pi_session_file,2,1)=':') AND bot_id IS NOT NULL AND instr(replace(pi_session_file,'\','/'),'/bots/'||bot_id||'/sessions/')>0
  AND substr(replace(pi_session_file,'\','/'),instr(replace(pi_session_file,'\','/'),'/bots/'||bot_id||'/sessions/')+length('/bots/'||bot_id||'/sessions/'))<>'' AND substr(replace(pi_session_file,'\','/'),instr(replace(pi_session_file,'\','/'),'/bots/'||bot_id||'/sessions/')+length('/bots/'||bot_id||'/sessions/')) NOT IN ('.','..') AND instr(substr(replace(pi_session_file,'\','/'),instr(replace(pi_session_file,'\','/'),'/bots/'||bot_id||'/sessions/')+length('/bots/'||bot_id||'/sessions/')),'/')=0;

UPDATE runs SET session_file='bots/'||bot_id||'/sessions/'||substr(replace(session_file,'\','/'),instr(replace(session_file,'\','/'),'/bots/'||bot_id||'/sessions/')+length('/bots/'||bot_id||'/sessions/'))
WHERE session_file IS NOT NULL AND (substr(session_file,1,1) IN ('/','\') OR substr(session_file,2,1)=':') AND bot_id IS NOT NULL AND instr(replace(session_file,'\','/'),'/bots/'||bot_id||'/sessions/')>0
  AND substr(replace(session_file,'\','/'),instr(replace(session_file,'\','/'),'/bots/'||bot_id||'/sessions/')+length('/bots/'||bot_id||'/sessions/'))<>'' AND substr(replace(session_file,'\','/'),instr(replace(session_file,'\','/'),'/bots/'||bot_id||'/sessions/')+length('/bots/'||bot_id||'/sessions/')) NOT IN ('.','..') AND instr(substr(replace(session_file,'\','/'),instr(replace(session_file,'\','/'),'/bots/'||bot_id||'/sessions/')+length('/bots/'||bot_id||'/sessions/')),'/')=0;

UPDATE routine_runs SET session_file='bots/'||bot_id||'/sessions/'||substr(replace(session_file,'\','/'),instr(replace(session_file,'\','/'),'/bots/'||bot_id||'/sessions/')+length('/bots/'||bot_id||'/sessions/'))
WHERE session_file IS NOT NULL AND (substr(session_file,1,1) IN ('/','\') OR substr(session_file,2,1)=':') AND bot_id IS NOT NULL AND instr(replace(session_file,'\','/'),'/bots/'||bot_id||'/sessions/')>0
  AND substr(replace(session_file,'\','/'),instr(replace(session_file,'\','/'),'/bots/'||bot_id||'/sessions/')+length('/bots/'||bot_id||'/sessions/'))<>'' AND substr(replace(session_file,'\','/'),instr(replace(session_file,'\','/'),'/bots/'||bot_id||'/sessions/')+length('/bots/'||bot_id||'/sessions/')) NOT IN ('.','..') AND instr(substr(replace(session_file,'\','/'),instr(replace(session_file,'\','/'),'/bots/'||bot_id||'/sessions/')+length('/bots/'||bot_id||'/sessions/')),'/')=0;

-- The parked checkpoint repeats the run's session file; recovery requires both to match.
UPDATE routine_runs SET wait_checkpoint=json_set(wait_checkpoint,'$.sessionFile','bots/'||json_extract(wait_checkpoint,'$.botId')||'/sessions/'||substr(replace(json_extract(wait_checkpoint,'$.sessionFile'),'\','/'),instr(replace(json_extract(wait_checkpoint,'$.sessionFile'),'\','/'),'/bots/'||json_extract(wait_checkpoint,'$.botId')||'/sessions/')+length('/bots/'||json_extract(wait_checkpoint,'$.botId')||'/sessions/')))
WHERE wait_checkpoint IS NOT NULL AND json_valid(wait_checkpoint) AND json_type(wait_checkpoint,'$.sessionFile')='text'
  AND json_extract(wait_checkpoint,'$.sessionFile') IS NOT NULL AND (substr(json_extract(wait_checkpoint,'$.sessionFile'),1,1) IN ('/','\') OR substr(json_extract(wait_checkpoint,'$.sessionFile'),2,1)=':') AND json_extract(wait_checkpoint,'$.botId') IS NOT NULL AND instr(replace(json_extract(wait_checkpoint,'$.sessionFile'),'\','/'),'/bots/'||json_extract(wait_checkpoint,'$.botId')||'/sessions/')>0
  AND substr(replace(json_extract(wait_checkpoint,'$.sessionFile'),'\','/'),instr(replace(json_extract(wait_checkpoint,'$.sessionFile'),'\','/'),'/bots/'||json_extract(wait_checkpoint,'$.botId')||'/sessions/')+length('/bots/'||json_extract(wait_checkpoint,'$.botId')||'/sessions/'))<>'' AND substr(replace(json_extract(wait_checkpoint,'$.sessionFile'),'\','/'),instr(replace(json_extract(wait_checkpoint,'$.sessionFile'),'\','/'),'/bots/'||json_extract(wait_checkpoint,'$.botId')||'/sessions/')+length('/bots/'||json_extract(wait_checkpoint,'$.botId')||'/sessions/')) NOT IN ('.','..') AND instr(substr(replace(json_extract(wait_checkpoint,'$.sessionFile'),'\','/'),instr(replace(json_extract(wait_checkpoint,'$.sessionFile'),'\','/'),'/bots/'||json_extract(wait_checkpoint,'$.botId')||'/sessions/')+length('/bots/'||json_extract(wait_checkpoint,'$.botId')||'/sessions/')),'/')=0;
